<template>
	<div class="compact-calendar-widget">
		<!-- Header mit Ansichts-Auswahl & Navigation -->
		<div class="calendar-header">
			<div class="header-top">
				<div class="view-selector">
					<button
						:class="{ active: currentView === 'week' }"
						@click="setView('week')">
						{{ t('compact_calendar_widget', 'Week') }}
					</button>
					<button
						:class="{ active: currentView === 'month' }"
						@click="setView('month')">
						{{ t('compact_calendar_widget', 'Month') }}
					</button>
					<button
						:class="{ active: currentView === 'year' }"
						@click="setView('year')">
						{{ t('compact_calendar_widget', 'Year') }}
					</button>
				</div>
				<span v-if="loading" class="icon-loading-small" />
			</div>

			<!-- Datum-Navigation (Pfeile & Aktuell) -->
			<div class="date-navigation">
				<button class="nav-btn" :title="t('compact_calendar_widget', 'Previous')" @click="navigate(-1)">
					&#8249;
				</button>
				<button class="today-btn" @click="resetToToday">
					{{ t('compact_calendar_widget', 'Current') }}
				</button>
				<button class="nav-btn" :title="t('compact_calendar_widget', 'Next')" @click="navigate(1)">
					&#8250;
				</button>
			</div>
		</div>

		<!-- Kalender-Ansichten -->
		<div class="calendar-body" :class="{ 'is-year-view': currentView === 'year' }">
			<!-- WOCHE / MONAT -->
			<div v-if="currentView !== 'year'" class="standard-view">
				<div class="month-title">
					{{ monthLabel }}
				</div>
				<div class="weekdays-grid">
					<span v-for="day in weekDays" :key="day">{{ day }}</span>
				</div>
				<div class="days-grid">
					<div
						v-for="(day, idx) in currentGrid"
						:key="idx"
						class="day-cell"
						:class="{
							'other-month': !day.inMonth,
							'has-events': day.events.length > 0,
							'is-today': day.isToday
						}"
						@click="openCalendarApp(day.date)">
						<span class="day-number">{{ day.dayNumber }}</span>

						<!-- Popover bei Hover -->
						<div v-if="day.events.length > 0" class="event-popover">
							<div class="popover-date">
								{{ formatDateHeader(day.date) }}
							</div>
							<ul>
								<li v-for="ev in day.events" :key="ev.id || ev.title">
									<strong>{{ formatTime(ev.start || ev.dtstart) }}</strong> {{ ev.title || ev.summary }}
									<span v-if="ev.location" class="location">({{ ev.location }})</span>
								</li>
							</ul>
						</div>
					</div>
				</div>
			</div>

			<!-- JAHR -->
			<div v-else class="year-view">
				<div
					v-for="m in 12"
					:key="m"
					:ref="isCurrentMonth(m - 1) ? 'currentMonth' : null"
					class="year-month-card">
					<div class="year-month-title">
						{{ getMonthName(m - 1) }}
					</div>
					<div class="year-weekdays-grid">
						<span v-for="day in weekDays" :key="day">{{ day[0] }}</span>
					</div>
					<div class="year-days-grid">
						<div
							v-for="(day, idx) in getYearMonthGrid(m - 1)"
							:key="idx"
							class="year-day-cell"
							:class="{
								'empty-slot': !day.inMonth,
								'has-events': day.inMonth && day.events.length > 0,
								'is-today': day.inMonth && day.isToday
							}"
							@click="day.inMonth && openCalendarApp(day.date)">
							<span v-if="day.inMonth">{{ day.dayNumber }}</span>

							<div v-if="day.inMonth && day.events.length > 0" class="event-popover">
								<div class="popover-date">
									{{ formatDateHeader(day.date) }}
								</div>
								<ul>
									<li v-for="ev in day.events" :key="ev.id || ev.title">
										<strong>{{ formatTime(ev.start || ev.dtstart) }}</strong> {{ ev.title || ev.summary }}
									</li>
								</ul>
							</div>
						</div>
					</div>
				</div>
			</div>
		</div>
	</div>
</template>

<script>
import axios from '@nextcloud/axios'
import { generateUrl } from '@nextcloud/router'
import { translate as t, translatePlural as n, getFirstDay, getDayNamesShort, getLocale } from '@nextcloud/l10n'

export default {
	name: 'CompactCalendar',
	data() {
		return {
			currentView: 'week',
			selectedDate: new Date(),
			events: [],
			loading: false,
		}
	},
	computed: {
		// 1. Ersten Tag der Woche ermitteln (0 = Sonntag, 1 = Montag)
		firstDayOfWeek() {
			return getFirstDay()
		},
		// 2. Lokalisierte Wochentage auf 2 Zeichen kürzen & nach Wochenstart ausrichten
		weekDays() {
			const dayNames = getDayNamesShort().map(day => day.replace('.', '').slice(0, 2))

			if (this.firstDayOfWeek === 1) {
				// Montag ist Start: Sonntag nach hinten schieben
				return [...dayNames.slice(1), dayNames[0]]
			}
			return dayNames
		},
		// 3. Monatsname in der Sprache des Benutzers
		monthLabel() {
			return this.selectedDate.toLocaleDateString(getLocale(), { month: 'long', year: 'numeric' })
		},
		eventsByDate() {
			const map = {}
			this.events.forEach(ev => {
				const startVal = ev.start?.dateTime || ev.start || ev.dtstart
				if (!startVal) return

				let isoDate = ''
				if (typeof startVal === 'string' && startVal.length >= 10) {
					isoDate = startVal.substring(0, 10)
				} else {
					const d = new Date(startVal)
					if (isNaN(d.getTime())) return
					isoDate = this.toLocalIsoDate(d)
				}

				if (!map[isoDate]) {
					this.$set(map, isoDate, [])
				}
				map[isoDate].push(ev)
			})
			return map
		},
		currentGrid() {
			if (this.currentView === 'week') {
				return this.generateWeekGrid(this.selectedDate)
			}
			return this.generateMonthGrid(this.selectedDate.getFullYear(), this.selectedDate.getMonth())
		}
	},
	mounted() {
		this.fetchEvents()
	},
	methods: {
		toLocalIsoDate(d) {
			const year = d.getFullYear()
			const month = String(d.getMonth() + 1).padStart(2, '0')
			const day = String(d.getDate()).padStart(2, '0')
			return `${year}-${month}-${day}`
		},
		openCalendarApp(targetDate) {
			if (!targetDate) return
			const isoDate = this.toLocalIsoDate(targetDate)

			const targetUrl = generateUrl(`/apps/calendar/dayGridMonth/${isoDate}`)
			window.location.href = targetUrl
		},
		setView(view) {
			this.currentView = view
			this.fetchEvents()

			if (view === 'year') {
				this.scrollToCurrentMonth()
			}
		},
		navigate(direction) {
			const d = new Date(this.selectedDate)

			if (this.currentView === 'week') {
				d.setDate(d.getDate() + (direction * 7))
			} else if (this.currentView === 'month') {
				d.setMonth(d.getMonth() + direction)
			} else if (this.currentView === 'year') {
				d.setFullYear(d.getFullYear() + direction)
			}

			this.selectedDate = d
			this.fetchEvents()

			if (this.currentView === 'year') {
				this.scrollToCurrentMonth()
			}
		},
		resetToToday() {
			this.selectedDate = new Date()
			this.fetchEvents()

			if (this.currentView === 'year') {
				this.scrollToCurrentMonth()
			}
		},
		isCurrentMonth(monthIndex) {
			const now = new Date()
			return this.selectedDate.getFullYear() === now.getFullYear() && monthIndex === now.getMonth()
		},
		scrollToCurrentMonth() {
			this.$nextTick(() => {
				const currentMonthEl = this.$refs.currentMonth
				const target = Array.isArray(currentMonthEl) ? currentMonthEl[0] : currentMonthEl

				if (target) {
					target.scrollIntoView({
						behavior: 'smooth',
						block: 'start'
					})
				}
			})
		},
		fetchEvents() {
			this.loading = true
			let startDate, endDate

			if (this.currentView === 'week') {
				const grid = this.generateWeekGrid(this.selectedDate)
				startDate = this.toLocalIsoDate(grid[0].date)
				endDate = this.toLocalIsoDate(grid[6].date)
			} else if (this.currentView === 'month') {
				const year = this.selectedDate.getFullYear()
				const month = this.selectedDate.getMonth()

				const firstDay = new Date(year, month, 1)
				const lastDay = new Date(year, month + 1, 0)

				startDate = this.toLocalIsoDate(firstDay)
				endDate = this.toLocalIsoDate(lastDay)
			} else if (this.currentView === 'year') {
				const year = this.selectedDate.getFullYear()
				startDate = `${year}-01-01`
				endDate = `${year}-12-31`
			}

			const targetDate = this.toLocalIsoDate(this.selectedDate)
			const url = generateUrl(`/apps/compact_calendar_widget/api/events?range=${this.currentView}&date=${targetDate}&start=${startDate}&end=${endDate}`)

			axios.get(url)
				.then(response => {
					this.events = response.data || []
				})
				.catch(error => {
					console.error('Fehler beim Laden der Termine', error)
				})
				.finally(() => {
					this.loading = false
				})
		},
		getDayOffset(dayOfWeek) {
			if (this.firstDayOfWeek === 1) { // Montag
				return dayOfWeek === 0 ? 6 : dayOfWeek - 1
			}
			return dayOfWeek // Sonntag
		},
		generateMonthGrid(year, month) {
			const grid = []
			const firstDay = new Date(year, month, 1)
			const lastDay = new Date(year, month + 1, 0)

			const dayOffset = this.getDayOffset(firstDay.getDay())

			const prevMonthLastDay = new Date(year, month, 0).getDate()
			for (let i = dayOffset - 1; i >= 0; i--) {
				grid.push(this.createDayObject(new Date(year, month - 1, prevMonthLastDay - i), false))
			}

			for (let d = 1; d <= lastDay.getDate(); d++) {
				grid.push(this.createDayObject(new Date(year, month, d), true))
			}

			const remaining = 42 - grid.length
			for (let i = 1; i <= remaining; i++) {
				grid.push(this.createDayObject(new Date(year, month + 1, i), false))
			}

			return grid
		},
		generateWeekGrid(date) {
			const grid = []
			const now = new Date(date)
			const dayOffset = this.getDayOffset(now.getDay())

			const firstDayOfWeekDate = new Date(now)
			firstDayOfWeekDate.setDate(now.getDate() - dayOffset)

			for (let i = 0; i < 7; i++) {
				const day = new Date(firstDayOfWeekDate)
				day.setDate(firstDayOfWeekDate.getDate() + i)
				grid.push(this.createDayObject(day, true))
			}
			return grid
		},
		getYearMonthGrid(monthIndex) {
			return this.generateMonthGrid(this.selectedDate.getFullYear(), monthIndex)
		},
		createDayObject(dateObj, inMonth) {
			const isoDate = this.toLocalIsoDate(dateObj)
			const todayIso = this.toLocalIsoDate(new Date())

			return {
				date: dateObj,
				dayNumber: dateObj.getDate(),
				inMonth: inMonth,
				isToday: isoDate === todayIso,
				events: this.eventsByDate[isoDate] || []
			}
		},
		getMonthName(index) {
			return new Date(this.selectedDate.getFullYear(), index, 1).toLocaleDateString(getLocale(), { month: 'short' })
		},
		formatDateHeader(dateObj) {
			return dateObj.toLocaleDateString(getLocale(), { weekday: 'short', day: '2-digit', month: '2-digit' })
		},
		formatTime(isoString) {
			if (!isoString) return ''
			const d = new Date(isoString)
			if (isNaN(d.getTime())) return ''
			return d.toLocaleTimeString(getLocale(), { hour: '2-digit', minute: '2-digit' })
		}
	}
}
</script>

